/* In-memory workspace prototype. No network, persistence, authentication or model execution. */
const clone = v => JSON.parse(JSON.stringify(v));
const LOCAL_KEYS=['unit','unitGrade','hint','attempt','correct','exam','submitted','feedback','planAccepted','planMinutes','messages','draft','goal','reflections','corrections','discussion','teaching','planner','tempMessages'];
function seedWorkspace(id,name,unit,grade,type='project',sample=null){return {id,name,type,archived:false,sample,data:{unit,unitGrade:grade,hint:0,attempt:false,correct:false,exam:false,submitted:false,feedback:'',planAccepted:false,planMinutes:20,messages:[],draft:'',goal:'独立解释'+unit+'中的关键依据',reflections:[],corrections:[],discussion:{round:0,posts:[],verified:false},teaching:{turns:[],reported:false},tempMessages:[],planner:{inputs:{subjective:'我能跟着算，但有时说不清每一步为什么这样做。',textbook:'自编开发教材摘要：理解条件、选择表示方法，并检查结果的适用范围。',syllabus:'课标知识点摘要：用恰当的数学语言说明依据，发展推理与模型意识。',exam:'本项目检查点：无辅助完成一道平行任务，并解释关键步骤。'},candidate:null,history:[],active:{version:'baseline-v1',content:'# Skill.md · 项目基线\n先尝试 → 按需提示 → 验证 → 讲回 → 独立检查。\n所有教学动作服从 R-01…R-10。'},serial:0}}}}
const WorkspaceStore={activeId:'p-equation',items:[seedWorkspace('p-equation','折扣与方程 · 两周计划','方程与应用','七年级','project',{n:12,values:[68,62,72,58,64,70],before:[48,45,56,42,50,52],mastery:68,independent:76,hints:'2.4 → 1.1'}),seedWorkspace('p-function','从图像理解一次函数','一次函数','八年级','project',{n:8,values:[72,68,57,76,60,66],before:[54,48,46,59,45,52],mastery:62,independent:70,hints:'2.0 → 1.4'}),seedWorkspace('p-geometry','全等三角形 · 证明练习','三角形与证明','八年级')],current(){return this.items.find(x=>x.id===this.activeId)},save(data){const x=this.current();for(const k of LOCAL_KEYS)x.data[k]=clone(data[k])},activate(id){const x=this.items.find(x=>x.id===id&&!x.archived);if(!x)return null;this.activeId=id;return clone(x.data)},formal(){return this.items.filter(x=>x.type==='project')}};
const originalTemplates={...pages};
const studentPages=['home','projects','units','plan','study','review','roundtable','teach','evidence','planner','tempchat','settings'];
const adminPages=['dashboard','bank','audit','runs','harness','config'];
const labelsV2={home:'今日学习',projects:'项目与会话',units:'数学单元',plan:'学习计划',study:'数学陪学',review:'错题与复习',roundtable:'圆桌研讨',teach:'我教 AI',evidence:'成长证据',planner:'规划与策略',tempchat:'临时会话',settings:'偏好与数据',dashboard:'试点概览',bank:'知识点与题库',audit:'内容与解答复核',runs:'交互与运行记录',harness:'策略评审',config:'配置与权限'};
function currentSpace(){return WorkspaceStore.current()}
function flushWorkspace(){if(APP_ROLE==='student')WorkspaceStore.save(state)}
function isTemp(){return currentSpace().type==='temp'}
function examLocked(){return state.exam&&!state.submitted}
function hydrateSpace(id){const data=WorkspaceStore.activate(id);if(data)Object.assign(state,data);return !!data}
function switchSpace(id){flushWorkspace();if(!hydrateSpace(id))return toast('先恢复已归档的项目');if(isTemp())state.page='tempchat';else if(state.page==='tempchat')state.page='home';state.scope='project';render();toast('当前空间：'+currentSpace().name)}
function switchRole(){toast('学生端与管理端使用独立 HTML 入口，请分别打开。')}
function go(p){const allow=APP_ROLE==='admin'?adminPages:studentPages;if(!allow.includes(p))return toast('请使用对应端的独立入口');state.page=p;render();window.scrollTo(0,0);$('#rail').classList.remove('open');location.hash=p}
function contextBar(){const x=currentSpace();return `<div class="context-bar ${isTemp()?'temp':''}"><div><b>${isTemp()?'临时探索':'学习项目'} · ${esc(x.name)}</b><small>${isTemp()?'这段对话独立保存于当前演示，不自动进入计划、复习或成长画像。':'陪学、复习、圆桌、教学练习与局部证据，均属于这个项目。'}</small></div>${btn('管理空间',"go('projects')",'text')}</div>`}
function render(){state.role=APP_ROLE;flushWorkspace();const admin=APP_ROLE==='admin',x=currentSpace();const nav=admin?[['dashboard','试点概览','home'],['bank','知识点与题库','bank'],['audit','内容与解答复核','audit'],['runs','交互与运行记录','people'],['harness','策略评审','plan'],['config','配置与权限','settings']]:[['home','今日学习','home'],['projects','项目与会话','units'],['units','数学单元','bank'],...(isTemp()?[['tempchat','临时对话','study'],['evidence','全局成长证据','evidence']]:[['plan','学习计划','plan'],['study','数学陪学','study'],['review','错题与复习','review'],['roundtable','圆桌研讨','people'],['teach','我教 AI','audit'],['evidence','成长证据','evidence'],['planner','规划与策略','plan']]),['settings','偏好与数据','settings']];$('#nav').innerHTML=nav.map(([p,t,i])=>`<button class="${state.page===p?'on':''}" onclick="go('${p}')">${icon(i)}${t}</button>`).join('');$('#navLabel').textContent=admin?'内容与试点治理':'工作空间与学习';$('#scope').textContent=admin?'独立管理工作台':x.name;$('#breadcrumb').textContent=labelsV2[state.page]||'';$('#personName').textContent=admin?'内容管理员':'林同学';$('#personNote').textContent=admin?'管理端 · 独立入口':isTemp()?'临时探索 · 不自动形成画像':state.unitGrade+' · 演示学习档案';$('#avatar').textContent=admin?'管':'林';$('#projects').classList.toggle('hidden',admin);if(!admin){$('#projects').innerHTML=workspacePicker();$('#rail').insertBefore($('#projects'),$('#navLabel'))}const blocked=!admin&&isTemp()&&['plan','study','review','roundtable','teach','planner'].includes(state.page);$('#page').innerHTML=(admin?'':contextBar())+(blocked?blockedTemp():pages[state.page]());document.title='桂子问津 · '+(admin?'管理端':'学生端')+' · '+labelsV2[state.page]}
function workspacePicker(){return `<div class="label">当前工作空间</div><div class="workspace-picker"><select aria-label="切换项目或临时会话" onchange="switchSpace(this.value)">${WorkspaceStore.items.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${x.id===currentSpace().id?'selected':''}>${x.type==='temp'?'临时 · ':'项目 · '}${esc(x.name)}</option>`).join('')}</select><div class="workspace-actions">${btn('+ 项目',"createProject()")}${btn('+ 临时',"createTemp()")}</div></div><div class="session-list">${WorkspaceStore.items.filter(x=>!x.archived).slice(-5).map(x=>`<button class="${x.id===currentSpace().id?'on':''}" onclick="switchSpace('${x.id}')"><span class="dot" style="background:${x.type==='temp'?'var(--gold)':'var(--green)'}"></span>${esc(x.name)}</button>`).join('')}</div>`}
function blockedTemp(){return `<div class="blocked-panel"><h2>临时会话保留自由探索的空间</h2><p class="lead">项目计划、圆桌、我教 AI 和局部成长证据需要正式项目上下文。你可以返回临时对话，或创建一个新项目。</p><div class="row wrap" style="justify-content:center;margin-top:22px">${btn('继续临时对话',"go('tempchat')",'primary')}${btn('创建学习项目',"createProject()")}</div></div>`}
function createTemp(){flushWorkspace();const n=WorkspaceStore.items.filter(x=>x.type==='temp').length+1;const x=seedWorkspace('temp-'+Date.now(),'临时探索 '+n,'自由数学探索','未指定','temp');WorkspaceStore.items.push(x);hydrateSpace(x.id);go('tempchat')}
function createProject(){modal('创建一个数学学习项目',`<div class="field"><label for="spaceName">项目名称</label><input id="spaceName" maxlength="45" placeholder="例如：用图像理解一次函数"></div><div class="field"><label for="spaceUnit">起始数学单元</label><select id="spaceUnit">${units.map(u=>`<option value="${esc(u[1])}">${u[0]} · ${u[1]}</option>`).join('')}</select></div><p class="tiny muted">新项目从空学习档案开始，临时会话不会自动导入。</p>`,'创建项目',()=>{const name=$('#spaceName').value.trim(),unit=$('#spaceUnit').value;if(!name)return toast('请给项目起一个名字');flushWorkspace();const u=units.find(x=>x[1]===unit);const x=seedWorkspace('p-'+Date.now(),name,unit,u[0]);WorkspaceStore.items.push(x);hydrateSpace(x.id);closeModal();go('home')})}
function renameSpace(id){const x=WorkspaceStore.items.find(x=>x.id===id);modal('重命名工作空间',`<div class="field"><label for="renameSpace">名称</label><input id="renameSpace" maxlength="45" value="${esc(x.name)}"></div>`,'保存名称',()=>{const v=$('#renameSpace').value.trim();if(!v)return toast('名称不能为空');x.name=v;closeModal();render()})}
function archiveSpace(id){const x=WorkspaceStore.items.find(x=>x.id===id);modal(x.archived?'恢复项目':'归档工作空间',`<p class="muted">${x.archived?'恢复后可继续学习，原记录保留。':'归档只隐藏入口，项目中的作答、反思、圆桌与策略版本仍保留。正式项目仍可贡献全局历史证据。'}</p>`,x.archived?'恢复':'确认归档',()=>{flushWorkspace();x.archived=!x.archived;if(x.id===currentSpace().id&&x.archived){const next=WorkspaceStore.items.find(y=>!y.archived);if(next)hydrateSpace(next.id);else createTemp()}closeModal();go('projects')})}
pages.projects=()=>head('PROJECTS & TEMPORARY SESSIONS','一段探索，一个独立的空间。','项目用于持续学习；临时会话适合即时提问，默认不进入正式画像。',`<div class="row wrap">${btn('+ 临时会话',"createTemp()")}${btn('+ 新建项目',"createProject()",'primary')}</div>`)+`<div class="grid three">${WorkspaceStore.items.map(x=>`<div class="card workspace-card ${x.id===currentSpace().id?'current':''}"><div class="row" style="justify-content:space-between"><span class="pill ${x.type==='temp'?'gold':''}">${x.archived?'已归档':x.type==='temp'?'临时会话':'正式项目'}</span>${x.id===currentSpace().id?'<span class="tiny muted">当前空间</span>':''}</div><h2>${esc(x.name)}</h2><p class="tiny muted">${esc(x.data.unit)} · ${esc(x.data.unitGrade)}</p><div class="stat-inline">${x.type==='temp'?x.data.tempMessages.filter(m=>m.user).length+' 条提问 · 不进入画像':x.data.messages.filter(m=>m.user).length+' 条本次陪学输入 · '+x.data.discussion.posts.length+' 条圆桌观点'}</div><div class="row wrap">${!x.archived?btn('进入',`switchSpace('${x.id}');go('${x.type==='temp'?'tempchat':'home'}')`,'soft'):''}${btn('重命名',`renameSpace('${x.id}')`)}${btn(x.archived?'恢复':'归档',`archiveSpace('${x.id}')`)}</div></div>`).join('')}</div><p class="context-note">演示状态仅在当前页面内保存。切换空间会恢复对应的草稿、计划、提示级别、反思、研讨和策略版本。归档不会清除记录。</p>`;
pages.home=()=>{if(isTemp())return pages.tempchat();const x=currentSpace(),s=x.sample;return head('YOUR PROJECT, YOUR PACE','从这个项目的一小步开始。',esc(x.name)+' · 在尝试、核查和讲回之间建立自己的理解。',btn('查看项目计划',"go('plan')"))+`<div class="grid two"><div class="stack"><div class="card hero"><div><div class="hero-label">${esc(state.unit)} / ${state.unitGrade}</div><h2 class="serif">先说出猜想，<br>再为它找到依据。</h2><p>陪学、圆桌与我教 AI 共享当前项目，学习记录各自保留。换一个项目，就回到另一段探索。</p>${btn('继续数学陪学 '+icon('arrow'),"go('study')",'primary')}</div>${art}</div><div class="grid three">${metric('演示独立检测',s?s.independent+'<small>%</small>':'—',s?'当前项目示例证据':'尚无独立检测证据')}${metric('你的项目反思',state.reflections.length+'<small>条</small>','本次页面中保留的方法')}${metric('圆桌参与',state.discussion.posts.length+'<small>条</small>','当前项目中的观点')}</div><div class="card"><div class="card-head"><h2>用不同的方式理解数学</h2><span class="tiny muted">当前项目内的学习方式</span></div>${[['数学陪学','先尝试，再获得适当提示','study','study'],['圆桌研讨','比较观点，发现反例，核查共同结论','roundtable','people'],['我教 AI','向虚拟学弟讲清楚一个误区','teach','audit']].map(([t,d,p,i])=>`<div class="task"><div class="tile-icon">${icon(i)}</div><div><h3>${t}</h3><p>${d}</p></div>${btn('进入',`go('${p}')`,'soft')}</div>`).join('')}</div></div><div class="stack"><div class="card"><h2>这个项目的上下文</h2><div class="kv"><span>当前计划</span><strong>${state.planAccepted?'学生已确认':'草案待确认'}</strong></div><div class="kv"><span>当前 Skill</span><strong>${esc(state.planner.active.version)}</strong></div><div class="kv"><span>局部证据</span><strong>${s?s.n+' 条示例证据':'等待学习证据'}</strong></div><p class="insight">根据主观反馈、学习证据和课程依据生成新的策略草案，改动保留理由与版本。</p>${btn('查看规划与策略',"go('planner')",'text')}</div><div class="card"><div class="card-head"><h2>素养的多个侧面</h2><span class="pill">项目局部</span></div>${radarSvg(s?.values,s?.before)}<p class="tiny muted">展示推理、表达与建模等维度的证据组织方式，不是固定能力评分。</p>${btn('查看完整成长证据',"state.scope='project';go('evidence')",'text')}</div></div></div>`};
function selectUnit(u,g){flushWorkspace();let x=WorkspaceStore.items.find(x=>x.type==='project'&&!x.archived&&x.data.unit===u);if(!x){x=seedWorkspace('p-'+Date.now(),u+' · 我的学习项目',u,g);WorkspaceStore.items.push(x)}hydrateSpace(x.id);go('study')}
function learningModes(){return `<div class="scope-tabs" style="margin-bottom:20px">${[['study','陪学'],['roundtable','圆桌研讨'],['teach','我教 AI']].map(([p,t])=>`<button class="${state.page===p?'on':''}" onclick="go('${p}')">${t}</button>`).join('')}</div>`}
pages.study=()=>learningModes()+originalTemplates.study();
function modeLocked(){return `<div class="blocked-panel"><span class="pill gold">独立检测进行中</span><h2 style="margin-top:15px">请先完成或结束当前检测</h2><p class="lead">圆桌与可教智能体会提供解题帮助，检测提交前暂时不可使用。</p>${btn('返回当前检测',"go('study')",'primary')}</div>`}
function discussionScenario(){if(state.unit.includes('函数'))return {title:'y = kx + 1，总是随 x 增大而上升吗？',claim:'只要是一次函数，图像就会向右上方走。',turns:[['举例席','当 k = 2 时，x 从 0 到 1，y 从 1 到 3，的确上升。这个例子支持的是所有 k，还是只支持 k = 2？'],['质疑席','取 k = −1，x 从 0 到 1，y 从 1 到 0。这个反例提醒我们：原观点漏掉了哪个条件？'],['总结席','目前分歧落在 k 的符号。请你给出修订后的说法，再交给核查席对照函数关系。']],conclusion:'对一次函数 y = kx + 1（k ≠ 0），k > 0 时随 x 增大而增大；k < 0 时随 x 增大而减小。',refs:'代入表格 · k = 2 与 k = −1 · 函数增减性条件'};if(/三角形|几何|圆/.test(state.unit))return {title:'看起来一样大，就能证明全等吗？',claim:'图上量出的两条边相等，就足以证明三角形全等。',turns:[['举例席','示意图里两条线段看起来接近，可以作为提出猜想的线索。'],['质疑席','示意图可能不按比例绘制。相等关系应该来自已知条件、定义还是已证定理？'],['总结席','需要区分观察和证明。请你为这个观点补上条件来源，并说明应选择的判定依据。']],conclusion:'测量和视觉观察能帮助猜想，但不能独自证明全等。证明需列出有依据的对应关系，并满足全等判定条件。',refs:'题目条件 · 定义/已证结论 · 全等判定要求'};return {title:'先折扣后减价，与先减价后折扣一样吗？',claim:'都是打八折和减 10 元，改变顺序不会改变价格。',turns:[['举例席','原价 100 元时，两种顺序分别得到 70 元和 72 元，说明“总是一样”需要重新检查。'],['质疑席','一个例子足以反驳“总是一样”，但如果要说明一般差异，还需要比较含 x 的表达式。'],['总结席','可比较 0.8x − 10 与 0.8(x − 10)。请你解释减去的 10 元是否参与折扣，再修订最初的观点。']],conclusion:'在原价 x ≥ 10 的示例条件下，两种表达式相差 2 元，先打折再减 10 元更便宜。运算顺序对应不同的数量关系。',refs:'自编题 EQ-014 · x ≥ 10 · 分配律与差值核查'}}
pages.roundtable=()=>{if(examLocked())return modeLocked();const q=discussionScenario(),d=state.discussion;return learningModes()+head('COMPARE · QUESTION · CHECK','把不同观点，放到同一张桌上。',esc(currentSpace().name)+' · 三个角色提供不同视角，由你参与推理。')+`<div class="roundtable-layout"><div class="card"><div class="card-head"><h2>${q.title}</h2><span class="pill gold">多角色模板演示</span></div><div class="notice">待核查的观点：“${q.claim}”</div><div class="seats">${['举例席','质疑席','总结席'].map((t,i)=>`<div class="seat"><span class="seat-letter">${['例','疑','归'][i]}</span><div><b>${t}</b><br><small>${['用例子检查猜想','寻找条件与反例','整理分歧，不抢结论'][i]}</small></div></div>`).join('')}</div><div class="thread">${d.round===0?'<div class="empty">先听一轮观点，也可以先写下你的猜测。</div>':q.turns.slice(0,d.round).map(([r,t],i)=>`<div class="round-turn"><span class="seat-letter">${['例','疑','归'][i]}</span><div><b class="tiny">${r}</b><small> · 待核查发言</small><p>${t}</p></div></div>`).join('')}${d.posts.map(t=>`<div class="round-turn"><span class="seat-letter">我</span><div><b class="tiny">我的观点</b><p>${esc(t)}</p></div></div>`).join('')}</div><div class="field"><label for="roundInput">你的解释、反例或修订</label><textarea id="roundInput" placeholder="你同意哪一部分？还缺什么依据？"></textarea></div><div class="row wrap">${btn(d.round<3?'听下一轮观点':'三席已发言',"nextRound()",d.round<3?'primary':'')}${btn('提交我的观点',"postRound()")}${btn('核查共同结论',"verifyDiscussion()",'soft')}</div>${d.verified?`<div class="feedback"><b>结论经过示例核查，仍可提出异议</b><p>${q.conclusion}</p><p class="tiny muted" style="margin-top:8px">核查依据：${q.refs}。这里是人工编写的核查模板，并非在线对抗委员会。</p></div>`:''}</div><div class="stack"><div class="card"><h2>这场讨论到哪里了？</h2><div class="kv"><span>三席发言</span><strong>${d.round} / 3</strong></div><div class="kv"><span>你的观点</span><strong>${d.posts.length} 条</strong></div><div class="kv"><span>共同结论</span><strong>${d.verified?'已核查 · 示例':'尚未核查'}</strong></div><p class="insight">多角色说法可以有分歧。归纳后的结论需经过核查，才能成为学生可见的正式教学结论。</p></div><div class="card"><h2>本次证据</h2><p class="lead">只写入当前项目。你的观点与核查记录可在项目成长证据中查看，暂不自动折算成素养分数。</p>${btn('查看项目证据',"state.scope='project';go('evidence')",'text')}</div></div></div>`};
function nextRound(){if(examLocked())return toast('检测期间暂停研讨');if(state.discussion.round>=3)return toast('三席已完成发言，请补充你的观点并核查');state.discussion.round++;state.discussion.verified=false;render()}
function postRound(){const t=$('#roundInput').value.trim();if(!t)return toast('请先写下一条自己的观点');state.discussion.posts.push(t);state.discussion.verified=false;render()}
function verifyDiscussion(){if(state.discussion.round<3||!state.discussion.posts.length)return toast('先听完三席观点，并留下至少一条自己的解释');state.discussion.verified=true;render()}
function teachScenario(){if(state.unit.includes('函数'))return {mis:'“一次函数的 k 只改变高度，不会改变倾斜方向。”',sample:'k 改变斜率。比如 k = 1 时随 x 增大而上升，k = −1 时下降；b 才表示与 y 轴的交点。',probe:'如果把 k 改成 −2，你会怎样向我解释图像的变化？',check:v=>/k|斜率/.test(v)&&/负|下降|−1|-1/.test(v)};if(/几何|三角形|圆/.test(state.unit))return {mis:'“图上看起来一样长，就能当作证明中的相等条件。”',sample:'示意图不一定按比例绘制。相等关系要来自已知条件、定义或已证定理；例如公共边 AD 与自己相等。',probe:'如果重新画图后两边看起来不一样了，证明依据会改变吗？',check:v=>/已知|定义|定理|公共边/.test(v)&&/不一定|不能|依据|比例/.test(v)};return {mis:'“−(2x − 3) 去括号后是 −2x − 3，因为只把第一项变号。”',sample:'外面的负号相当于乘以 −1，要作用于括号中的每一项，所以结果是 −2x + 3。取 x = 0 时，原式与化简后的式子都等于 3。',probe:'如果换成 −(x + 4)，哪些项需要改变符号？为什么？',check:v=>/每一项|两项|分配律/.test(v)&&/\+\s*3|加3|加 3/.test(v)}}
pages.teach=()=>{if(examLocked())return modeLocked();const t=teachScenario(),d=state.teaching;return learningModes()+head('LEARN BY TEACHING','这一次，由你把道理讲清楚。',esc(currentSpace().name)+' · 向虚拟学弟解释、举例，再检查是否真的讲明白。')+`<div class="roundtable-layout"><div class="card"><div class="teach-profile"><div class="learner-avatar">学</div><div><h2>虚拟学弟</h2><p class="tiny muted">带有公开标记的预设误区 · 可能说错</p></div></div><div class="notice">它当前的错误想法：${t.mis}</div><div class="phase-line"><span class="on">发现误区</span><span class="${d.turns.length?'on':''}">解释与举例</span><span class="${d.turns.some(x=>x.match)?'on':''}">追问与迁移</span><span class="${d.reported?'on':''}">教学证据</span></div>${d.turns.map(x=>`<div class="message user"><b>我解释</b><p>${esc(x.text)}</p></div><div class="message"><b>虚拟学弟 · 模板回应</b><p>${x.match?'我注意到你补充了关键依据。'+t.probe:'我还没弄清楚每一步的依据。能否再举一个例子，或指出我漏掉的条件？'}</p></div>`).join('')}<div class="field"><label for="teachInput">试着教会它</label><textarea id="teachInput" placeholder="先指出具体误区，再解释依据或举例。"></textarea></div><div class="row wrap">${btn('把我的解释讲给它',"submitTeaching()",'primary')}${btn('填入示例解释',"document.getElementById('teachInput').value=teachScenario().sample")}${btn('整理教学证据',"finishTeaching()",'soft')}</div>${d.reported?`<div class="feedback"><b>TeachReport · 当前项目</b><p>保留了 ${d.turns.length} 次解释尝试，其中 ${d.turns.filter(x=>x.match).length} 次包含模板要求的关键词与例子线索。</p><p class="tiny muted">这是可观察的教学过程记录，不代表真实学习效果或自动证明解释质量。</p></div>`:''}</div><div class="stack"><div class="card"><h2>怎样算讲清楚？</h2><div class="kv"><span>指出具体错误</span><strong>不是只说“你错了”</strong></div><div class="kv"><span>补充依据</span><strong>条件、定义或运算规则</strong></div><div class="kv"><span>举例或检验</span><strong>换一个值或问题</strong></div><p class="insight">本原型用模板识别关键表达，正式版本需依据结构化 rubric、验证器与人工抽查。</p></div><div class="card"><h2>回到你的学习</h2><p class="lead">这些解释可以为项目中的“数学表达、推理意识”提供待评价证据。是否形成素养判断还需进一步核查。</p>${btn('查看项目证据',"state.scope='project';go('evidence')",'text')}</div></div></div>`};
function submitTeaching(){const v=$('#teachInput').value.trim();if(!v)return toast('先写下你的解释');state.teaching.turns.push({text:v,match:teachScenario().check(v)});state.teaching.reported=false;render()}
function finishTeaching(){if(!state.teaching.turns.length)return toast('先完成一次解释，再整理证据');state.teaching.reported=true;render()}
pages.tempchat=()=>{if(!isTemp())return `<div class="blocked-panel"><h2>打开一段临时探索</h2><p class="lead">临时对话不自动成为任何项目的成长证据。</p>${btn('新建临时会话',"createTemp()",'primary')}</div>`;return head('TEMPORARY EXPLORATION','先自由提问，不急着建立画像。','这条路线适合即时疑问；需要持续计划时，再新建一个学习项目。',btn('创建正式项目',"createProject()"))+`<div class="grid two"><div class="card"><div class="temp-thread">${state.tempMessages.length?state.tempMessages.map(m=>`<div class="message ${m.user?'user':''}"><b>${m.user?'我':'津津 · 演示回应'}</b><p>${esc(m.text)}</p></div>`).join(''):'<div class="empty">你现在想探索哪个数学问题？</div>'}</div><div class="field temp-composer"><label for="tempInput">你的临时问题</label><textarea id="tempInput" placeholder="例如：为什么负数乘负数得到正数？"></textarea></div>${btn('发送',"sendTemp()",'primary')}</div><div class="card"><h2>这段探索的归属</h2><div class="kv"><span>空间类型</span><strong>临时会话</strong></div><div class="kv"><span>计划与复习</span><strong>不自动生成</strong></div><div class="kv"><span>全局或项目画像</span><strong>默认不纳入</strong></div><p class="insight">创建正式项目时从空档案开始，不会自动复制这段对话。将来若支持迁移，需要明确选择资料并再次确认。</p></div></div>`};
function sendTemp(){const t=$('#tempInput').value.trim();if(!t)return toast('先写下一条问题');state.tempMessages.push({user:true,text:t},{user:false,text:'我们可以从一个具体例子开始。你现在的猜想是什么？这条模板回应只保留在当前临时会话。'});render()}

const competencyNames=['数学抽象','逻辑推理','运算与检验','直观想象','数学建模','数学表达'];
function radarSvg(values,before){const c=[205,150],r=98,point=(i,v)=>{const a=i*Math.PI/3-Math.PI/2;return [c[0]+Math.cos(a)*r*v/100,c[1]+Math.sin(a)*r*v/100]},polygon=vs=>vs.map((v,i)=>point(i,v).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 410 300" role="img" aria-label="六个数学素养观察维度的演示雷达图，${values?'当前与早期示例对照':'尚无证据'}">${[25,50,75,100].map(v=>`<polygon points="${polygon(Array(6).fill(v))}" fill="none" stroke="var(--line)"/>`).join('')}${competencyNames.map((n,i)=>`<line x1="205" y1="150" x2="${point(i,100)[0]}" y2="${point(i,100)[1]}" stroke="var(--line)"/><text x="${point(i,135)[0]}" y="${point(i,130)[1]+4}" text-anchor="middle">${n}</text>`).join('')}${before?`<polygon points="${polygon(before)}" fill="none" stroke="var(--gold)" stroke-dasharray="4 4" stroke-width="1.5"/>`:''}${values?`<polygon points="${polygon(values)}" fill="var(--soft)" fill-opacity=".65" stroke="var(--green)" stroke-width="2"/>${values.map((v,i)=>`<circle cx="${point(i,v)[0]}" cy="${point(i,v)[1]}" r="3" fill="var(--green)"/>`).join('')}`:'<text x="205" y="153" text-anchor="middle">等待正式项目证据</text>'}</svg>`}
function evidenceSummary(global){const spaces=global?WorkspaceStore.formal():[currentSpace()].filter(x=>x.type==='project');const valid=spaces.filter(x=>x.sample);const n=valid.reduce((s,x)=>s+x.sample.n,0);const avg=key=>n?competencyNames.map((_,i)=>Math.round(valid.reduce((s,x)=>s+x.sample[key][i]*x.sample.n,0)/n)):null;return {spaces,n,values:avg('values'),before:avg('before'),reflections:spaces.reduce((s,x)=>s+x.data.reflections.length,0),rounds:spaces.reduce((s,x)=>s+x.data.discussion.posts.length,0),teaching:spaces.reduce((s,x)=>s+x.data.teaching.turns.length,0)}}
pages.evidence=()=>{if(isTemp())state.scope='global';const global=state.scope==='global',s=evidenceSummary(global),x=currentSpace();return head('FROM EVIDENCE TO UNDERSTANDING','素养的变化，要能回到具体证据。','全局看跨项目的数学学习；局部看当前项目中的方法、尝试与反思。',`<div class="scope-tabs"><button class="${global?'on':''}" onclick="state.scope='global';render()">全局宏观</button><button class="${!global?'on':''}" onclick="localEvidence()">项目局部</button></div>`)+`<div class="notice">${global?'汇总全部正式数学项目，含归档项目的历史证据；排除临时会话。':'当前项目：'+esc(x.name)+'，不混入其他项目的作答和研讨。'} 雷达坐标为界面示意，尚未形成经过验证的测量量表。</div><div class="grid four">${metric('正式项目',s.spaces.length+'<small>个</small>',global?'跨项目纵向观察':'当前项目独立查看')}${metric('参考证据包',s.n+'<small>条</small>','全部为预置模拟示例')}${metric('本次圆桌观点',s.rounds+'<small>条</small>','过程证据，不自动换算分数')}${metric('本次讲解尝试',s.teaching+'<small>次</small>','来自我教 AI 的解释记录')}</div>${growthTrends(s)}<div class="grid equal" style="margin-top:18px"><div class="card"><div class="card-head"><h2>数学素养 · 六个观察维度</h2><span class="pill">${global?'全局示例':'项目示例'}</span></div>${radarSvg(s.values,s.before)}<div class="legend"><span><i></i>当前示例</span><span><i class="gold"></i>较早示例</span></div><p class="insight">维度用于组织证据，不给学生贴固定能力标签。图上的 0–100 仅是示意刻度，不是考试分数或自主性指数。</p></div><div class="card"><div class="card-head"><h2>维度与可观察行为</h2>${btn('这些判断不符合我',"correction()",'text')}</div><div class="competency-bars">${competencyNames.map((n,i)=>`<div class="competency-bar"><span>${n}</span><div class="line"><i style="width:${s.values?s.values[i]:0}%"></i></div><b>${s.values?s.values[i]:'—'}</b></div>`).join('')}</div><p class="insight">抽象：从情境提取关系；推理：补全条件与论证；检验：主动核查结果；想象：图式转换；建模：选择与解释模型；表达：讲清方法与依据。</p><div class="evidence-chain"><span>原始作答 / 研讨</span>→<span>有来源的小结</span>→<span>待验证的素养判断</span></div></div><div class="card"><div class="card-head"><h2>${global?'各项目的证据贡献':'本项目过程证据'}</h2><span class="tiny muted">可追溯 · 不混同来源</span></div>${s.spaces.map(p=>`<div class="evidence-detail"><div><b class="tiny">${esc(p.name)}${p.archived?' · 已归档':''}</b><p>${p.sample?p.sample.n+' 条示例包':'暂无预置评测'} · ${p.data.reflections.length} 条反思 · ${p.data.discussion.posts.length} 条圆桌观点 · ${p.data.teaching.turns.length} 次讲解</p></div>${btn('看依据',`showProjectEvidence('${p.id}')`,'text')}</div>`).join('')||'<div class="empty">没有正式项目证据</div>'}<p class="context-note">全局雷达仅对预置示例包按条数加权演示。新的对话与教学尝试保留为待评价证据，不会自动抬高雷达数值。</p></div><div class="card"><div class="card-head"><h2>${global?'当前项目的主观体验':'主观体验与画像纠正'}</h2><span class="pill gold">学生自述</span></div><p class="serif" style="font-size:20px;line-height:1.9;margin-bottom:15px">${isTemp()?'全局视图不吸收这段临时会话。':esc(state.planner.inputs.subjective)}</p>${!isTemp()?btn('补充我的体验',"editSubjective()")+`<p class="insight">你的自述与作答证据分开标记。规划 Agent 可以同时参考，但不能把“感觉懂了”直接当成已掌握。</p>${btn('送入本项目规划',"go('planner')",'text')}`:'<p class="lead">进入正式项目后，可以补充自述、反思与画像纠正。</p>'}</div></div>`};
function localEvidence(){if(isTemp())return toast('临时会话没有项目局部画像，请切换正式项目');state.scope='project';render()}
function editSubjective(){modal('补充你的学习体验',`<div class="field"><label for="selfReport">这段学习对你来说怎样？</label><textarea id="selfReport">${esc(state.planner.inputs.subjective)}</textarea></div><p class="tiny muted">来源标记为学生自述，不能覆盖客观作答记录。</p>`,'保留到当前项目',()=>{const v=$('#selfReport').value.trim();if(!v)return toast('请写下一条自己的体验');state.planner.inputs.subjective=v;closeModal();render()})}
function showProjectEvidence(id){const p=WorkspaceStore.items.find(x=>x.id===id);modal('证据来源 · '+p.name,`<div class="kv"><span>数据来源</span><strong>模拟示例 / 当前页面交互</strong></div><div class="kv"><span>原始作答</span><strong>${p.data.attempt?'已有本次示例提交':'尚未提交本次作答'}</strong></div><div class="kv"><span>研讨结论</span><strong>${p.data.discussion.verified?'模板核查已完成':'尚未形成核查结论'}</strong></div>${p.data.discussion.posts.map(t=>`<div class="source-item"><b class="tiny">学生观点</b><p>${esc(t)}</p></div>`).join('')}${p.data.teaching.turns.map(t=>`<div class="source-item"><b class="tiny">我教 AI · 解释记录</b><p>${esc(t.text)}</p></div>`).join('')}${p.data.reflections.map(t=>`<div class="source-item"><b class="tiny">学生反思</b><p>${esc(t.text)}</p></div>`).join('')}<p class="insight">正式实现需为每条来源分配事件 ID，并关联项目、时间、版本和授权。本页无真实学生数据。</p>`,'知道了')}
pages.review=()=>{if(examLocked())return modeLocked();const x=currentSpace();return head('REVISIT WITH CONTEXT','在这个项目里，重新理解一次。',esc(x.name)+' · 复习记录与其他项目分开。')+`<div class="grid two"><div class="card"><div class="card-head"><h2>当前项目的复习线索</h2><span class="pill">${esc(state.unit)}</span></div>${x.sample?`<div class="task"><div><h3>${state.unit.includes('函数')?'图像变化与 k 的条件':'数量关系与分配律'}</h3><p>来源：本项目预置示例记录，需换一道平行任务再次检查。</p></div>${btn('回到项目练习',"go('study')",'soft')}</div>`:'<div class="empty">这个新项目还没有已评测错题。先完成一次陪学与独立检查。</div>'}${state.attempt?`<div class="new-evidence"><b class="tiny">本次作答待复习</b><p class="tiny muted">${esc(state.feedback)}</p><p class="tiny" style="margin-top:10px">${esc(state.draft)}</p></div>`:''}${state.reflections.map(t=>`<div class="source-item"><b class="tiny">你留下的方法</b><p>${esc(t.text)}</p></div>`).join('')}</div><div class="card"><h2>项目隔离的复习队列</h2><div class="kv"><span>计划时长</span><strong>${state.planMinutes} 分钟</strong></div><div class="kv"><span>独立尝试</span><strong>${state.attempt?'本次已提交':'等待本次提交'}</strong></div><div class="kv"><span>错误判断纠正</span><strong>${state.corrections.length} 条</strong></div><p class="insight">当前页面只展示这个项目的线索。全局学习者模型可以跨项目积累，但不能让其他项目的错题混进本项目列表。</p>${btn('补充一条判断纠正',"correction()",'text')}</div></div>`};

const PlannerModel={fingerprint(c){const text=JSON.stringify([c.projectId,c.baseVersion,c.version,c.sources,c.skill]);let hash=2166136261;for(let i=0;i<text.length;i++){hash^=text.charCodeAt(i);hash=Math.imul(hash,16777619)}return (hash>>>0).toString(16)},make(space,inputs,serial,objective){const version='candidate-v'+serial;const sources={subjective:{kind:'student_self_report',text:inputs.subjective},reflections:{kind:'student_reflection_and_correction',text:space.data.reflections.map(x=>x.text).concat(space.data.corrections).join('；')||'暂无本项目反思与画像纠正'},textbook:{kind:'textbook_excerpt_unverified',text:inputs.textbook},syllabus:{kind:'curriculum_excerpt_unverified',text:inputs.syllabus},exam:{kind:'checkpoint_or_syllabus_excerpt_unverified',text:inputs.exam},objective:{kind:'synthetic_project_evidence',text:objective}};const skill=`# Skill.md · ${space.name}\nversion: ${version}\nproject_id: ${space.id}\nbase_version: ${space.data.planner.active.version}\nstatus: candidate\n\n## 目标与适用范围\n- 限于当前初中数学项目：${space.data.unit}\n- 学生确认计划后才调整正式学习任务。\n\n## 输入与来源\n- 学生自述：[self-report] ${inputs.subjective}\n- 反思与画像纠正：[self-report] ${sources.reflections.text}\n- 学习证据：[synthetic] ${objective}\n- 教材/讲义：[unverified excerpt] ${inputs.textbook}\n- 课标：[unverified excerpt] ${inputs.syllabus}\n- 考纲/检查点：[unverified excerpt] ${inputs.exam}\n\n## 建议调整的软策略\n+ 每次练习增加一处“为什么”的依据说明。\n+ 以一道平行任务检查学生是否能独立迁移。\n+ 在当前知识点补充一次反例比较或我教 AI。\n+ 根据复习证据调整节奏，不单独追求减少提示。\n\n## Harness 执行约定\n- 题目绑定知识点与内容版本。\n- 动作提案经过规则引擎，结论附验证/复核状态。\n- 状态更新保留来源，真实与模拟数据隔离。\n\n## 只读边界\n- R-01…R-10 不可被此草案修改。\n- 考试帮助隔离、计划确认权与数据最小化保持有效。\n- 不修改系统提示、安全规则或模型权重。\n\n## 生效门\n- 场景检查 → 人工评审 → 学生确认 → 版本化激活。\n- 保留上个版本，支持人工回滚。`;const c={id:space.id+'-c'+serial,projectId:space.id,projectName:space.name,baseVersion:space.data.planner.active.version,version,skill,sources,status:'draft',checked:false,reviewed:false};c.fingerprint=this.fingerprint(c);return c},checks(c){return [{label:'来源字段齐全，主观与客观分开',pass:Object.values(c.sources).every(s=>s.text.trim())},{label:'限定当前项目与软策略范围',pass:!!c.projectId&&c.skill.includes('建议调整的软策略')},{label:'硬约束明确只读',pass:c.skill.includes('R-01…R-10 不可被此草案修改')},{label:'保留学生确认与回滚条件',pass:c.skill.includes('学生确认')&&c.skill.includes('回滚')}]}};
function objectiveBundle(){return `${currentSpace().sample?currentSpace().sample.n+'条预置示例证据':'暂无预置评测包'}；本次作答${state.attempt?'已提交':'未提交'}；${state.reflections.length}条反思；${state.discussion.posts.length}条研讨观点；${state.teaching.turns.length}次教学解释。过程记录尚未自动证明学习增益。`}
pages.planner=()=>{const p=state.planner,c=p.candidate,active=p.active;return head('PLANNING AGENT · HARNESS','让新证据，成为可评审的策略调整。',esc(currentSpace().name)+' · 输入来源 → 候选 Skill.md → 检查 → 评审 → 学生确认。')+`<div class="audit-notice">原型只按静态模板生成草案，不调用规划模型、不改写真实 Skill.md。教材、课标与考纲输入先标记为待核验摘录；候选策略只能调整软参数和任务安排。</div><div class="planner-layout" style="margin-top:20px"><div class="card planner-inputs"><div class="card-head"><h2>规划的输入依据</h2><span class="pill">当前项目</span></div><div class="field"><label for="plannerSelf">① 主观信息 · 学生自述 / 反思</label><textarea id="plannerSelf" oninput="state.planner.inputs.subjective=this.value">${esc(p.inputs.subjective)}</textarea></div><div class="notice">② 客观学习过程 · 来源由项目自动绑定<br>${esc(objectiveBundle())}</div>${[['textbook','③ 教材 / 讲义依据'],['syllabus','④ 课程标准 / 知识点要求'],['exam','⑤ 考纲 / 阶段检查点']].map(([key,label])=>`<div class="field"><label for="source-${key}">${label}</label><textarea id="source-${key}" oninput="state.planner.inputs.${key}=this.value">${esc(p.inputs[key])}</textarea><label class="file-label tiny muted">导入文本摘录 <input type="file" accept=".txt,.md" onchange="importSource(this,'${key}')"></label></div>`).join('')}<p class="context-note">仅接受本地 .txt/.md 摘录；页面不上传文件。教材版本、页码、课程标准条目等请写入摘录，生成草案保留原文来源。</p>${btn('生成候选规划与 Skill.md',"generateCandidate()",'primary')}</div><div class="stack"><div class="card"><div class="card-head"><h2>${c?'候选 Skill.md':'当前 Skill.md'}</h2><span class="pill ${c?'gold':''}">${esc(c?.version||active.version)}</span></div><div class="status-flow">${['候选草案','演示检查','人工评审','学生确认'].map((t,i)=>`<span class="${c&&(i===0||i===1&&c.checked||i===2&&c.reviewed||i===3&&c.status==='active')?'done':''}">${i+1} · ${t}</span>`).join('')}</div><pre class="skill-preview">${esc(c?.skill||active.content)}</pre>${c?`<div class="workflow-row">${btn('运行演示检查',"checkCandidate()")}${btn('导出送管理端评审',"exportCandidate()")}</div><label class="file-label tiny muted">导入管理端评审回执 <input type="file" accept=".json" onchange="importReviewReceipt(this)"></label><div class="workflow-row">${btn('学生确认并模拟激活',"activateCandidate()",'primary')}${btn('撤回候选草案',"state.planner.candidate=null;render()")}</div>${c.checks?c.checks.map(r=>`<div class="check-result">${r.pass?'✓':'○'} ${r.label}</div>`).join(''):''}<p class="context-note">状态：${statusText(c.status)}。检查只检验模板结构与边界，不验证数学内容、实际教学效果或真实回归结果。</p>`:'<p class="context-note">填写左侧依据后生成候选。现有策略不会因为生成草案而被覆盖。</p>'}</div><div class="card"><div class="card-head"><h2>当前生效版本与谱系</h2><span class="pill">${esc(active.version)}</span></div><p class="tiny muted">当前项目保留 ${p.history.length} 次历史激活。没有通过评审和学生确认的草案不会替换当前版本。</p>${p.history.map(v=>`<div class="version-row"><b>${esc(v.version)} → ${esc(v.replacedBy)}</b><span>${v.rolledBack?'已回滚':'历史版本'}</span></div>`).join('')}<div class="row wrap" style="margin-top:18px">${btn('导出当前 Skill.md',"downloadText('Skill.md',state.planner.active.content,'text/markdown')")}${btn('回滚上个版本',"rollbackSkill()")}</div></div></div></div>`};
function statusText(s){return ({draft:'待检查',checked:'等待管理端评审回执',reviewed:'评审通过，等待学生确认',returned:'评审退回，需要修改',active:'已模拟激活',stale:'基线已变化，需要重新生成'})[s]||s}
function generateCandidate(){if(examLocked())return toast('检测期间不调整当前学习策略');const p=state.planner;if(Object.values(p.inputs).some(v=>!v.trim()))return toast('请补齐学生自述、教材、课标与检查点依据');flushWorkspace();p.serial++;p.candidate=PlannerModel.make(currentSpace(),clone(p.inputs),p.serial,objectiveBundle());render();toast('候选已生成，现有策略仍保持当前版本')}
function checkCandidate(){const c=state.planner.candidate;if(!c)return toast('先生成候选草案');if(c.status==='active')return toast('该版本已激活，无需重复检查');c.checks=PlannerModel.checks(c);c.checked=c.checks.every(x=>x.pass);c.reviewed=false;c.status=c.checked?'checked':'draft';render()}
function downloadText(name,text,type='application/json'){const blob=new Blob([text],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportCandidate(){const c=state.planner.candidate;if(!c?.checked)return toast('先完成演示检查，再导出送审');downloadText('wenjin-candidate-'+c.id+'.json',JSON.stringify({format:'wenjin-candidate-v1',candidate:c},null,2));toast('在独立管理端的“策略评审”中导入此文件')}
async function readLocalFile(input){const file=input.files?.[0];if(!file)return null;if(file.size>300000){toast('演示文件请小于 300 KB');input.value='';return null}return await file.text()}
async function importSource(input,key){const t=await readLocalFile(input);if(t===null)return;state.planner.inputs[key]='来源文件：'+input.files[0].name+'\n'+t.slice(0,12000);render();toast('摘录已加入当前项目，来源仍待核验')}
async function importReviewReceipt(input){try{const text=await readLocalFile(input);if(text===null)return;const r=JSON.parse(text),c=state.planner.candidate;if(!c||r.format!=='wenjin-review-v1'||r.candidateId!==c.id||r.projectId!==currentSpace().id||r.fingerprint!==c.fingerprint)throw Error('回执与当前项目候选不匹配');if(!c.checked||c.status==='active')throw Error('当前候选不在等待评审的状态');c.reviewed=r.decision==='approve';c.reviewNote=String(r.note||'');c.status=c.reviewed?'reviewed':'returned';render();toast('已导入演示评审回执；离线文件不构成真实身份认证')}catch(e){toast('无法导入：'+e.message)}}
function activateCandidate(){const p=state.planner,c=p.candidate;if(!c?.checked||!c.reviewed)return toast('需要演示检查和管理端评审回执，之后由学生确认');if(c.status==='active')return toast('这个版本已经激活');if(c.baseVersion!==p.active.version){c.status='stale';render();return toast('当前基线已变化，请重新生成候选')}modal('由你确认新的学习安排',`<p>拟激活 ${esc(c.version)}，限定项目「${esc(currentSpace().name)}」。</p><div class="diff"><ins>+ 增加依据讲解与平行任务核查</ins><br><ins>+ 按证据调整本项目复习节奏</ins></div><p class="tiny muted">教学硬约束保持只读。这里仅更新内存中的演示版本，正式执行仍需服务端门禁。</p>`,'确认并模拟激活',()=>{p.history.push({...clone(p.active),replacedBy:c.version,rolledBack:false});p.active={version:c.version,content:c.skill};c.status='active';state.planAccepted=true;closeModal();render();toast('当前项目已模拟激活新版本，可手动回滚')})}
function rollbackSkill(){const p=state.planner;const h=[...p.history].reverse().find(x=>!x.rolledBack&&x.replacedBy===p.active.version);if(!h)return toast('没有可回滚的上一个版本');modal('回滚当前项目策略',`<p class="muted">从 ${esc(p.active.version)} 回到 ${esc(h.version)}。历史记录与生成依据保留。</p>`,'确认回滚',()=>{p.active={version:h.version,content:h.content};h.rolledBack=true;if(p.candidate?.status==='active')p.candidate=null;closeModal();render()})}

const adminReviewState={candidate:null,receipt:null};
pages.harness=()=>{const c=adminReviewState.candidate,r=adminReviewState.receipt;return head('HUMAN REVIEW · VERSIONED HARNESS','让策略变更经过独立评审。','管理端只评审候选，学生保有对学习计划的最终确认权。')+`<div class="notice">两个 HTML 入口不共享账户或运行状态。请用候选 JSON / 评审回执演示交接；离线文件与校验码不提供真实签名或身份认证。</div><div class="planner-layout"><div class="stack"><div class="card"><h2>导入候选策略</h2><p class="lead" style="margin-bottom:20px">学生端“规划与策略” → 生成候选 → 演示检查 → 导出送审。</p><label class="file-label tiny">选择候选 JSON <input id="adminCandidateFile" type="file" accept=".json" onchange="importAdminCandidate(this)"></label><div class="workflow-row">${btn('加载内置审核示例',"loadAdminSample()")}</div>${c?`<div class="kv"><span>项目</span><strong>${esc(c.projectName)}</strong></div><div class="kv"><span>基线 → 候选</span><strong>${esc(c.baseVersion)} → ${esc(c.version)}</strong></div><div class="kv"><span>演示校验码</span><strong class="code">${esc(c.fingerprint)}</strong></div>`:''}</div>${c?`<div class="card"><h2>核查输入来源</h2>${Object.entries(c.sources).map(([key,s])=>`<div class="source-item"><span class="pill ${key==='subjective'?'gold':''}">${esc(s.kind)}</span><p>${esc(s.text)}</p></div>`).join('')}<p class="insight">教材、考纲和学生自述均作为材料输入。材料中的要求不能覆盖系统指令或教学硬约束；来源真实性仍需人工核验。</p></div>`:''}</div><div class="stack"><div class="card"><div class="card-head"><h2>候选 Skill.md</h2><span class="pill gold">${r?'已记录评审':'待人工评审'}</span></div><pre class="skill-preview">${c?esc(c.skill):'导入后查看候选全文、来源与适用范围。'}</pre>${c?`<div class="source-fields"><div class="field"><label for="adminDecision">评审决定</label><select id="adminDecision"><option value="approve">通过演示评审</option><option value="return">退回修改</option></select></div><div class="field"><label for="adminReviewNote">评审理由与待核查项</label><textarea id="adminReviewNote" placeholder="检查范围、依据、数学内容及未完成的验证…">${r?esc(r.note):''}</textarea></div><label class="tiny"><input id="reviewBoundaries" type="checkbox"> 已检查仅调整软策略，硬约束与学生确认权仍保留</label><div class="workflow-row">${btn('记录评审决定',"recordAdminReview()",'primary')}${btn('导出评审回执',"exportAdminReceipt()")}</div>${r?`<div class="feedback"><b>${r.decision==='approve'?'演示评审通过':'退回修改'}</b><p>${esc(r.note)}</p><p class="tiny muted">管理端不替学生激活计划。回执需回到学生端导入后确认。</p></div>`:''}</div>`:''}</div><div class="audit-notice">正式实现需有授权审核角色、不可篡改谱系、真正的冻结场景回归、灰度与回滚。当前页面的通过决定仅用于交互演示。</div></div></div>`};
function validCandidate(c){return !!c&&typeof c.id==='string'&&typeof c.projectId==='string'&&typeof c.projectName==='string'&&typeof c.skill==='string'&&c.skill.length<100000&&typeof c.baseVersion==='string'&&typeof c.version==='string'&&!!c.sources&&['subjective','objective','textbook','syllabus','exam'].every(k=>typeof c.sources[k]?.text==='string'&&typeof c.sources[k]?.kind==='string')&&c.checked===true&&c.fingerprint===PlannerModel.fingerprint(c)}
async function importAdminCandidate(input){try{const t=await readLocalFile(input);if(t===null)return;const d=JSON.parse(t);if(d.format!=='wenjin-candidate-v1'||!validCandidate(d.candidate))throw Error('候选结构、检查状态或校验码不匹配');adminReviewState.candidate=clone(d.candidate);adminReviewState.receipt=null;render();toast('候选已载入，等待独立评审')}catch(e){toast('无法载入：'+e.message)}}
function loadAdminSample(){const s=WorkspaceStore.items[0];const c=PlannerModel.make(s,s.data.planner.inputs,1,'12 条模拟证据与一条方法反思，仅供布局演示。');c.checked=true;c.status='checked';adminReviewState.candidate=c;adminReviewState.receipt=null;render()}
function recordAdminReview(){const c=adminReviewState.candidate;if(!c)return toast('先导入候选');const note=$('#adminReviewNote').value.trim();if(!note)return toast('请填写评审理由与待核查项');if(!$('#reviewBoundaries').checked)return toast('请先检查并确认策略边界');adminReviewState.receipt={format:'wenjin-review-v1',candidateId:c.id,projectId:c.projectId,fingerprint:c.fingerprint,decision:$('#adminDecision').value,note,reviewer:'演示内容审核者',authentication:'offline-demo-not-authenticated'};render();toast('评审决定已记录，可导出回执')}
function exportAdminReceipt(){if(!adminReviewState.receipt)return toast('先记录评审决定');downloadText('wenjin-review-'+adminReviewState.receipt.candidateId+'.json',JSON.stringify(adminReviewState.receipt,null,2));toast('回到学生端“规划与策略”导入回执')}
pages.dashboard=()=>originalTemplates.dashboard()+`<div class="card" style="margin-top:18px"><div class="card-head"><h2>项目策略的评审入口</h2><span class="pill">独立管理端</span></div><p class="lead">从学生端导入规划 Agent 的候选 Skill.md，核对输入来源、软策略变更和只读边界，再导出评审回执。学生确认后才在对应项目内模拟激活。</p><div class="row" style="margin-top:18px">${btn('进入策略评审',"go('harness')",'primary')}</div></div>`;
function showGuide(){modal(APP_ROLE==='admin'?'独立管理端 · 演示说明':'项目学习空间 · 演示说明',APP_ROLE==='admin'?'<p>管理端与学生端是两个独立的 HTML 页面，没有角色切换按钮。</p><p class="lead">题库与解答复核延续上一版；新增“策略评审”，可导入学生端导出的候选 JSON，审核后将回执带回学生端。</p><p class="insight">离线文件没有真实权限与签名能力。正式系统需要独立认证和服务端授权。</p>':'<p>这个原型用于确认：项目与临时会话是否清楚、项目内学习模式是否连贯、证据如何进入规划与策略评审。</p><p class="lead">左侧可新建项目与临时会话。圆桌研讨和我教 AI 都在当前项目中；切换项目会恢复各自的草稿和记录。</p><p class="lead">成长证据提供全局与局部素养可视化。规划与策略可生成候选 Skill.md，再通过文件与独立管理端演示评审。</p><p class="insight">全部是模拟数据与静态模板。刷新重置，不调用后端或模型，不修改真实 Skill.md。</p>','开始体验')}
function exportDemo(){flushWorkspace();const payload=APP_ROLE==='admin'?{role:'admin',source_kind:'synthetic',review:adminReviewState}:{role:'student',source_kind:'synthetic',activeWorkspace:WorkspaceStore.activeId,workspaces:WorkspaceStore.items,rule:'temporary sessions excluded from formal evidence'};downloadText('wenjin-'+APP_ROLE+'-demo.json',JSON.stringify(payload,null,2));toast('本次演示状态已导出')}
function evidenceDetail(){showProjectEvidence(currentSpace().id)}
if(APP_ROLE==='student'){hydrateSpace(WorkspaceStore.activeId);state.page=studentPages.includes(location.hash.slice(1))?location.hash.slice(1):'home'}else{state.page=adminPages.includes(location.hash.slice(1))?location.hash.slice(1):'dashboard'}
render();

function growthTrends(summary){const valid=summary.spaces.filter(x=>x.sample);const rate=summary.n?Math.round(valid.reduce((v,x)=>v+x.sample.independent*x.sample.n,0)/summary.n):null;return `<div class="grid equal" style="margin-top:18px"><div class="card"><div class="card-head"><h2>无辅助检测表现</h2><span class="pill">检测与素养分开呈现</span></div>${rate===null?'<div class="empty">等待这个项目的无辅助检测证据</div>':trendSvg([rate-18,rate-12,rate-5,rate],'%')}<p class="insight">模拟平行任务走势，用于展示撤除帮助后的表现；不是已验证的产品成效。记录需保留题目版本和帮助条件。</p></div><div class="card"><div class="card-head"><h2>脚手架使用变化</h2><span class="pill gold">结合独立表现解释</span></div>${rate===null?'<div class="empty">等待提示与独立作答记录</div>':trendSvg([2.4,2.0,1.5,1.1],'次',true)}<p class="insight">每题提示使用为示意数据。求助不被污名化；不能仅凭提示减少推断学习自主性提高。</p></div></div>`}
function trendSvg(values,suffix,descending=false){const max=descending?3:100,min=descending?0:40;const ys=values.map(v=>125-(v-min)/(max-min)*90),xs=[45,145,245,345];return `<svg class="chart" viewBox="0 0 390 165" role="img" aria-label="四个阶段的模拟趋势"><path class="gridline" d="M35 35H365 M35 80H365 M35 125H365"/><polyline class="curve" points="${xs.map((x,i)=>x+','+ys[i]).join(' ')}"/>${values.map((v,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="4" fill="var(--green)"/><text x="${xs[i]}" y="${ys[i]-10}" text-anchor="middle">${v}${suffix}</text><text x="${xs[i]}" y="155" text-anchor="middle">阶段 ${i+1}</text>`).join('')}</svg>`}

window.addEventListener('hashchange',()=>{const p=location.hash.slice(1),allowed=APP_ROLE==='admin'?adminPages:studentPages;if(allowed.includes(p)&&state.page!==p){state.page=p;render();window.scrollTo(0,0)}});
